import{_ as r,C as a,o as i,c as h,j as o,a as g,E as s,a2 as n}from"./chunks/framework.TaNiW7i8.js";const b=JSON.parse('{"title":"Settings","description":"","frontmatter":{"title":"Settings"},"headers":[],"relativePath":"en/guide/settings.md","filePath":"en/guide/settings.md"}'),l={name:"en/guide/settings.md"};function c(d,e,u,p,m,y){const t=a("Capture");return i(),h("div",null,[e[0]||(e[0]=o("h1",{id:"settings",tabindex:"-1"},[g("Settings "),o("a",{class:"header-anchor",href:"#settings","aria-label":'Permalink to "Settings"'},"​")],-1)),e[1]||(e[1]=o("p",null,"Settings gather everything you can adjust in Kessho: appearance, where the memory lives, sync, shortcuts, updates. They fit on a single page, and the language is changed elsewhere, in the sidebar.",-1)),s(t,{name:"reglages-apparence",alt:'Appearance settings: "Dark" has just been selected and the whole application switches to the dark theme.'}),e[2]||(e[2]=n('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Click <strong>Settings</strong> at the bottom of the sidebar (or press <strong>⌘,</strong>) to open the <strong>Settings</strong> tab.</p><ul><li><strong>On the left</strong>, the list of sections: <strong>Appearance</strong>, <strong>Memory</strong>, <strong>Sync</strong>, <strong>MCP connectors</strong>, <strong>Shortcuts</strong>, <strong>Updates</strong>, <strong>Features</strong>, <strong>Codebase map</strong>, <strong>About</strong> and <strong>Reset</strong>. Click a name to jump to its section.</li><li><strong>On the right</strong>, the page: all the sections one after another, with the current section&#39;s name staying pinned at the top as you scroll. The screen reopens where you left it.</li></ul><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="choose-the-appearance" tabindex="-1">Choose the appearance <a class="header-anchor" href="#choose-the-appearance" aria-label="Permalink to &quot;Choose the appearance&quot;">​</a></h3><p>In <strong>Appearance</strong>, click one of the three tiles: <strong>System</strong>, <strong>Light</strong> or <strong>Dark</strong>. The change is immediate. <strong>System</strong> follows the macOS setting; light and dark are treated as equals.</p><p>The &quot;Ask for confirmation before quitting with unsaved text&quot; checkbox decides whether Kessho asks you a question when you quit with a modified, unsaved note. It is ticked by default.</p><h3 id="change-the-language" tabindex="-1">Change the language <a class="header-anchor" href="#change-the-language" aria-label="Permalink to &quot;Change the language&quot;">​</a></h3><p>The language is not set in Settings: you pick it in the sidebar, at the bottom, with the button that shows the language code (<strong>EN</strong>).</p>',9)),s(t,{name:"reglages-langue",alt:"The language selector in the sidebar, open: French, English, German, Spanish, Russian."}),e[3]||(e[3]=n('<p>The menu offers <strong>Français</strong>, <strong>English</strong>, <strong>Deutsch</strong>, <strong>Español</strong> and <strong>Русский</strong>. Click the one you want.</p><h3 id="change-or-check-the-memory" tabindex="-1">Change or check the memory <a class="header-anchor" href="#change-or-check-the-memory" aria-label="Permalink to &quot;Change or check the memory&quot;">​</a></h3><p>The <strong>Memory</strong> section is a table of four rows:</p><ul><li><strong>Location</strong>: the folder of your memory. Click <strong>Change</strong> to pick another one in the folder picker; the choice is saved straight away. Closing the picker without choosing changes nothing.</li><li><strong>Content</strong>: what the memory holds, for example &quot;13 notes · 16 files · 89 KB&quot;.</li><li><strong>Previous installation</strong>: this row only appears if Kessho detects one that has not been taken over yet. It sends you to the banner on <a href="/Kessho/en/guide/home.html">Home</a> to resume the migration.</li><li><strong>Backup</strong>: says whether the memory is protected by git. &quot;None — your files are yours&quot;, &quot;Local git repository, no remote&quot; or &quot;Git repository synced with …&quot;.</li></ul><p>To pick a memory for the first time, see <a href="/Kessho/en/guide/vault.html">Choose your memory</a>.</p><h3 id="sync-the-memory" tabindex="-1">Sync the memory <a class="header-anchor" href="#sync-the-memory" aria-label="Permalink to &quot;Sync the memory&quot;">​</a></h3><p>The <strong>Sync</strong> section shows the repository&#39;s state and its actions: <strong>Sync</strong>, <strong>Pull</strong>, <strong>Push</strong>, the changes to commit, the remote and the agents&#39; automation. Everything is described in <a href="/Kessho/en/guide/sync.html">Sync</a>.</p><h3 id="connect-your-agents" tabindex="-1">Connect your agents <a class="header-anchor" href="#connect-your-agents" aria-label="Permalink to &quot;Connect your agents&quot;">​</a></h3><p>The <strong>MCP connectors</strong> section lists the AI clients detected on your computer and says which ones carry Kessho. See <a href="/Kessho/en/guide/agents.html">Connect your agents</a>.</p><h3 id="read-the-shortcuts-change-the-editor-s" tabindex="-1">Read the shortcuts, change the editor&#39;s <a class="header-anchor" href="#read-the-shortcuts-change-the-editor-s" aria-label="Permalink to &quot;Read the shortcuts, change the editor&#39;s&quot;">​</a></h3><p>The <strong>Shortcuts</strong> section has two tables.</p>',11)),s(t,{name:"reglages-raccourcis",alt:'The Shortcuts section of Settings: the "Bold" shortcut is being edited and the screen waits for the new key combination (Esc cancels).'}),e[4]||(e[4]=n('<ul><li>The first lists the application&#39;s shortcuts: <strong>⌘K</strong> open search, <strong>⌘,</strong> open settings, <strong>⌘W</strong> close the tab, <strong>⌘B</strong> show or hide the sidebar, <strong>⌥←</strong> and <strong>⌥→</strong> previous or next tab. It is read-only. On Windows, <strong>⌘</strong> becomes <strong>Ctrl</strong> and <strong>⌥</strong> becomes <strong>Alt</strong>.</li><li>The second, <strong>In the editor</strong>, lists the note editor&#39;s shortcuts. Those can be changed: click <strong>Change</strong> next to an action, type the new combination, <strong>Esc</strong> cancels. A combination is refused, with the reason, if it does not contain <strong>⌘</strong> (or <strong>Ctrl</strong>), if the system reserves it or if another action already uses it. <strong>Reset</strong> puts the original keys back for that action, <strong>Reset all</strong> for every action.</li></ul><p>Shortcuts do not apply while you are typing text. The editor&#39;s actions are listed in <a href="/Kessho/en/guide/atom.html">Atom and editor</a>.</p><h3 id="update-kessho" tabindex="-1">Update Kessho <a class="header-anchor" href="#update-kessho" aria-label="Permalink to &quot;Update Kessho&quot;">​</a></h3><p>In <strong>Updates</strong>:</p><ol><li>Read the <strong>Installed version</strong>.</li><li>Pick the <strong>Channel</strong>. A channel that cannot be reached is marked &quot;Channel unavailable&quot;, with the reason when it is known.</li><li>Click <strong>Check</strong>. The result reads &quot;Up to date — … is the latest published version.&quot; or &quot;Version … available.&quot;.</li><li>If a version is available, click <strong>Install and restart</strong>. If Kessho processes used by your AI agents are still running, Kessho tells you: <strong>Close and install</strong> closes them before replacing the program.</li></ol><p>At launch, Kessho queries the public channel once. If a newer version exists, a &quot;Version … available&quot; banner appears at the top: <strong>See the update</strong> opens this section, <strong>Later</strong> hides it until the next launch. Nothing is installed without your click. To turn this check off, untick <strong>Look for a public update at launch</strong>, in the same section.</p><h3 id="look-at-the-tiers" tabindex="-1">Look at the tiers <a class="header-anchor" href="#look-at-the-tiers" aria-label="Permalink to &quot;Look at the tiers&quot;">​</a></h3><p><strong>Features</strong> shows the <strong>Licence tiers</strong>: what each tier grants. It is read-only, these tiers are not settings.</p><h3 id="map-a-project-s-code" tabindex="-1">Map a project&#39;s code <a class="header-anchor" href="#map-a-project-s-code" aria-label="Permalink to &quot;Map a project&#39;s code&quot;">​</a></h3><p><strong>Codebase map</strong> measures how well a memory project&#39;s code is described.</p><ol><li>Type a project&#39;s name in <strong>Memory project</strong>, then click <strong>Scan</strong>.</li><li>Read the <strong>Coverage</strong> (&quot;N files described out of M&quot;), the <strong>Undocumented candidates</strong>, the <strong>Dead references</strong> and the <strong>Stale entries</strong>.</li><li>To add a folder to the scan, type it under <strong>Add a zone to scan</strong> and click <strong>Add</strong>.</li><li>To clean up, click <strong>Preview repair</strong>: the preview says how many dead references would be removed. <strong>Apply repair</strong> runs it.</li></ol><h3 id="see-the-version-and-the-notices" tabindex="-1">See the version and the notices <a class="header-anchor" href="#see-the-version-and-the-notices" aria-label="Permalink to &quot;See the version and the notices&quot;">​</a></h3><p><strong>About</strong> gives the <strong>Product</strong>, the <strong>Version</strong> and the <strong>Platform</strong>. <strong>Show third-party notices</strong> unfolds the licences of the open-source components Kessho includes; <strong>Hide third-party notices</strong> folds them back.</p><h3 id="reset" tabindex="-1">Reset <a class="header-anchor" href="#reset" aria-label="Permalink to &quot;Reset&quot;">​</a></h3><p><strong>Reset</strong> restarts the first-run wizard: click <strong>Relaunch Onboarding Wizard</strong>. The configuration is cleared; the memory and its contents are left untouched. See <a href="/Kessho/en/guide/first-run.html">First launch</a>.</p>',15))])}const k=r(l,[["render",c]]);export{b as __pageData,k as default};
